{"python":"import re, math

file = '41698_2026_1663_MOESM1_ESM.pdf'
sheets = [f'page{i}' for i in range(20, 25)]

def as_obj(x):
    return x if isinstance(x, dict) else {'value': x}

def num(v):
    try:
        return float(str(v).replace(',', '.').strip())
    except Exception:
        return None

all_candidates = []
for sheet in sheets:
    meta = tables[file][sheet]
    nrows = meta.nrows
    header_rows = []
    row_cells = {}
    for r in range(1, nrows + 1):
        vals = []
        for c in range(1, meta.ncols + 1):
            try:
                obj = as_obj(cell_ref(file, sheet, r, c))
            except Exception:
                continue
            v = obj.get('value')
            if v is None or not str(v).strip():
                continue
            ref = f'{file}/{sheet}/R{r}C{c}'
            ent = {'ref': ref, 'r': r, 'c': c, 'x': obj.get('x0', c * 50), 'value': str(v).strip()}
            vals.append(ent)
            row_cells.setdefault(r, []).append(ent)
        text = ' '.join(x['value'] for x in vals)
        if re.search(r'EVSS', text, re.I) and re.search(r'RECIST|response|DCR', text, re.I):
            header_rows.append(r)

    for hr in header_rows:
        headers = row_cells.get(hr, [])
        anchors = []
        for h in headers:
            t = h['value'].lower()
            kind = None
            if re.search(r'patient|id|case', t): kind = 'patient'
            elif re.search(r'evss', t): kind = 'score'
            elif re.search(r'recist|response|DCR', t): kind = 'truth'
            elif re.search(r'match|matching', t): kind = 'match'
            elif re.search(r'line', t): kind = 'line'
            if kind:
                anchors.append((h['x'], kind, h['value']))
        if not any(k == 'score' for _, k, _ in anchors):
            continue
        for r, cells_r in row_cells.items():
            if r <= hr:
                continue
            assigned = {}
            for ent in cells_r:
                kind, dist = min(((k, abs(ent['x'] - x)) for x, k, _ in anchors), key=lambda z: z[1])
                if dist < 45:
                    assigned.setdefault(kind, []).append(ent)
            row_text = ' '.join(e['value'] for e in cells_r)
            pidm = re.search(r'#?\b(\d{1,2})\b', row_text)
            score_ent = None
            if 'score' in assigned:
                for e in assigned['score']:
                    z = num(e['value'])
                    if z is not None and 0 <= z <= 100:
                        score_ent = e
                        break
            truth_ent = None
            pool = assigned.get('truth', []) + cells_r
            for e in pool:
                if re.fullmatch(r'(?i)(CR|SD|PD)', e['value'].strip()):
                    truth_ent = e
                    break
            match_text = ' '.join(e['value'] for e in assigned.get('match', [])) or row_text
            exact = re.search(r'(?i)\bexact\b', match_text) is not None
            if score_ent and truth_ent and pidm:
                all_candidates.append({
                    'id': 'patient_' + pidm.group(1) + '_line_' + str(r),
                    'score_ref': score_ent['ref'],
                    'truth_ref': truth_ent['ref'],
                    'score': num(score_ent['value']),
                    'truth': truth_ent['value'].upper(),
                    'exact': exact,
                    'sheet': sheet,
                    'row': r,
                    'text': row_text
                })

# Deduplicate identical patient/score/truth cells introduced by repeated header blocks.
seen = set()
candidates = []
for x in all_candidates:
    key = (x['score_ref'], x['truth_ref'])
    if key not in seen:
        seen.add(key)
        candidates.append(x)

exact_evaluable = [x for x in candidates if x['exact']]
# The seven exact, radiologically evaluable matched lines are the accuracy analysis set.
selected = exact_evaluable
if len(selected) != 7:
    # Fallback for tables where the match-type word is in a neighboring row rather than its own column.
    selected = [x for x in candidates if re.search(r'(?i)exact', x['text'])]
if len(selected) != 7:
    print('Candidate counts:', len(candidates), len(exact_evaluable))
    for x in candidates:
        print(x)
    raise RuntimeError('Expected seven exact radiologically evaluable matched treatment lines')

records = []
for x in selected:
    records.append({
        'id': x['id'],
        'score': {'ref': x['score_ref']},
        'truth': {'ref': x['truth_ref'], 'map': {'CR': 1, 'SD': 1, 'PD': 0}}
    })

CONTRACT = {
    'status': 'computed',
    'fields': {
        'unit': {'value': 'patient_regimen', 'evidence': ['article:p17', 'article:p20'], 'explanation': 'Each observation is a patient treatment line matched to an ex vivo regimen.'},
        'platform': {'value': 'organoid', 'evidence': ['article:p1', 'article:p5'], 'explanation': 'Drug responses were measured in organotypic tissue slice cultures.'},
        'readout': {'value': 'other', 'evidence': ['article:p12', 'article:p29'], 'explanation': 'EVSS is an equally weighted composite of CK7, CC3, and Ki67 treatment effects.'},
        'direction': {'value': 'higher_sensitive', 'evidence': ['article:p12', 'article:p17'], 'explanation': 'Higher EVSS denotes greater ex vivo sensitivity.'},
        'threshold_rule': {'value': 'fixed_numeric', 'evidence': ['article:p17', 'article:p48'], 'explanation': 'Sensitivity is classified at EVSS 50.'},
        'threshold_timing': {'value': 'not_reported', 'evidence': ['article:p29'], 'explanation': 'The median-derived cutoff was exploratory and not independently validated.'},
        'patient_mapping': {'value': 'individual_available', 'evidence': ['article:p17', 'article:p18'], 'explanation': 'Patient IDs, tested regimens, EVSS, and RECIST status are available for each matched treatment line.'},
        'regimen_match': {'value': 'matched', 'evidence': ['article:p17'], 'explanation': 'This seven-line accuracy set uses exact regimen matches with radiological response.'},
        'n_units': {'value': 7, 'evidence': [r['score_ref'] for r in records], 'explanation': 'Seven exact matched treatment lines have both EVSS and RECIST DCR status.'},
        'split': {'value': 'same_cohort', 'evidence': ['article:p29'], 'explanation': 'Score derivation and clinical correlation were performed in the same exploratory cohort.'}
    },
    'headline': {
        'metric': 'accuracy',
        'reported': 1.0,
        'reported_evidence': [x['score_ref'] for x in selected] + [x['truth_ref'] for x in selected],
        'threshold': 50,
        'op': '>=',
        'score_direction': 'higher',
        'records': records,
        'blocked_reason': ''
    },
    'notes': ['Truth is RECIST disease control: CR or SD = 1, PD = 0.', 'All seven selected treatment lines agree between EVSS classification and clinical DCR.']
}"}
